<?php
function catalogView(string $type,string $title,string $subtitle,array $fields): void {
 $tables=['product'=>'products','client'=>'clients','supplier'=>'suppliers'];$table=$tables[$type];
 ['rows'=>$rows,'edit'=>$edit]=catalogPageData($type);
 if(($_SESSION['role']??'')==='cliente'){echo '<div class="heading"><div><h1>Catálogo de productos</h1><small>Productos disponibles en Marash</small></div></div><div class="panel"><div class="table-scroll"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Disponibilidad</th></tr></thead><tbody>';foreach($rows as $r){echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['category']).'</td><td>'.e(money($r['price'])).'</td><td>'.((int)$r['stock']>0?'Disponible':'Agotado').'</td></tr>';}echo '</tbody></table></div></div>';return;}
 if(($_SESSION['role']??'')==='vendedor'){echo '<div class="heading"><div><h1>'.e($title).'</h1><small>Consulta de registros</small></div></div><div class="panel"><table><thead><tr>';foreach(array_slice($fields,0,3,true) as $label)echo '<th>'.e($label).'</th>';echo '</tr></thead><tbody>';foreach($rows as $r){echo '<tr>';foreach(array_slice($fields,0,3,true) as $key=>$label)echo '<td>'.e($key==='price'?money($r[$key]):$r[$key]).'</td>';echo '</tr>';}echo '</tbody></table></div>';return;}
 echo '<div class="heading"><div><h1>'.e($title).'</h1><small>'.e($subtitle).'</small></div></div><div class="two-col"><div class="panel"><h3>'.($edit?'Editar':'Nuevo').' '.e($type==='product'?'producto':($type==='client'?'cliente':'proveedor')).'</h3><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="type" value="'.e($type).'"><input type="hidden" name="id" value="'.e($edit['id']??'').'">';csrf();echo '<div class="form-grid">';
 foreach($fields as $key=>$label){$val=$edit[$key]??'';$required=in_array($key,['name','sku','category'],true)?'required':'';$inputType=in_array($key,['price','cost','stock'],true)?'number':($key==='email'?'email':'text');$extra=$inputType==='number'?'min="0" step="'.($key==='stock'?'1':'0.01').'"':'';echo '<label>'.e($label).'<input type="'.$inputType.'" name="'.e($key).'" value="'.e($val).'" '.$required.' '.$extra.'></label>';}
 echo '</div><div class="form-actions"><button class="primary" type="submit">Guardar cambios</button>';if($edit)echo '<a class="btn-link" href="?page='.e($table==='products'?'productos':($table==='clients'?'clientes':'proveedores')).'">Cancelar edición</a>';echo '</div></form></div><div class="panel"><h3>Registros ('.count($rows).')</h3><div class="table-scroll"><table><thead><tr>';foreach(array_slice($fields,0,$type==='product'?4:3,true) as $label)echo '<th>'.e($label).'</th>';echo '<th>Acciones</th></tr></thead><tbody>';
 foreach($rows as $r){echo '<tr>';foreach(array_slice($fields,0,$type==='product'?4:3,true) as $key=>$label){$v=$r[$key];if($key==='price')$v=money($v);echo '<td>'.e($v).'</td>';}echo '<td><div class="actions"><a class="btn-link" href="?page='.e($table==='products'?'productos':($table==='clients'?'clientes':'proveedores')).'&edit='.e($r['id']).'">Editar</a>';if(($_SESSION['role']??'')==='admin'){echo '<form method="post"><input type="hidden" name="action" value="delete"><input type="hidden" name="type" value="'.e($type).'"><input type="hidden" name="id" value="'.e($r['id']).'">';csrf();echo '<button class="secondary" data-confirm="¿Eliminar este registro?" type="submit">Eliminar</button></form>';}echo '</div></td></tr>';}
 echo '</tbody></table>';if(!$rows)echo '<p class="empty">No hay registros.</p>';echo '</div></div></div>';
}
